-- Integer key generated by the database, and a dimension rebuilt after day 22. Run after Lab 4 (three photos).
-- The day 21 dimension comes from the photos up to day 21, so the whole proof runs in one file.
-- Run with ON_ERROR_STOP off: the foreign key case ends in an error on purpose.
-- Writes only to its own schema, rebuilt on every run.
\pset border 1
\pset null '<nulo>'
DROP SCHEMA IF EXISTS ensaio_chave CASCADE;
CREATE SCHEMA ensaio_chave;

-- Same type 2 rule as silver.produtos_vigencia, limited to the photos taken up to a given day.
CREATE FUNCTION ensaio_chave.versoes_ate(ate date)
RETURNS TABLE (produto_id integer, nome text, preco numeric, valido_de date, valido_ate date)
LANGUAGE sql STABLE AS $$
    WITH fotos AS (
        SELECT f.id AS produto_id, f.preco, f._dia_referencia AS dia,
               lag(f.preco) OVER (PARTITION BY f.id ORDER BY f._dia_referencia) AS preco_anterior,
               row_number() OVER (PARTITION BY f.id ORDER BY f._dia_referencia) AS ordem
        FROM bronze.produtos_foto f WHERE f._dia_referencia <= ate
    ), mudancas AS (
        SELECT fotos.produto_id, fotos.preco, fotos.dia AS valido_de FROM fotos
        WHERE fotos.ordem = 1 OR fotos.preco IS DISTINCT FROM fotos.preco_anterior
    )
    SELECT m.produto_id, p.nome, m.preco, m.valido_de,
           lead(m.valido_de) OVER (PARTITION BY m.produto_id ORDER BY m.valido_de)
    FROM mudancas m JOIN silver.produtos p ON p.produto_id = m.produto_id
$$;

CREATE TABLE ensaio_chave.dim_id (
    produto_sk   integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    produto_id   integer NOT NULL,
    nome         text NOT NULL,
    preco_tabela numeric(12, 2) NOT NULL,
    valido_de    date NOT NULL,
    valido_ate   date
);
INSERT INTO ensaio_chave.dim_id (produto_id, nome, preco_tabela, valido_de, valido_ate)
SELECT produto_id, nome, preco, valido_de, valido_ate FROM ensaio_chave.versoes_ate(DATE '2026-10-21')
ORDER BY produto_id, valido_de;

\echo == 1. Dimensão no fim do dia 21: cinco versões, chaves de 1 a 5.
SELECT produto_sk, produto_id, nome, preco_tabela, valido_de, valido_ate FROM ensaio_chave.dim_id ORDER BY produto_sk;

-- The fact keeps the key it found on load day. The key stays stored when the dimension is rebuilt.
CREATE TABLE ensaio_chave.fct_id AS
SELECT i.pedido_id, i.item_seq, d.produto_sk, o.dia_local AS data_id, o.status, i.valor_item
FROM silver.itens i JOIN silver.pedidos o USING (pedido_id)
JOIN ensaio_chave.dim_id d ON d.produto_id = i.produto_id AND o.dia_local >= d.valido_de
                          AND (d.valido_ate IS NULL OR o.dia_local < d.valido_ate)
WHERE o.dia_local <= DATE '2026-10-21';
CREATE TABLE ensaio_chave.leitura_antes AS
SELECT DISTINCT f.produto_sk, d.nome, d.preco_tabela
FROM ensaio_chave.fct_id f JOIN ensaio_chave.dim_id d USING (produto_sk);

\echo == 2. Fato guardada no dia 21, lida pela dimensão do dia 21.
SELECT d.nome, count(*) AS itens, sum(f.valor_item) AS valor
FROM ensaio_chave.fct_id f JOIN ensaio_chave.dim_id d USING (produto_sk) GROUP BY 1 ORDER BY 1;
SELECT count(*) AS itens_guardados, sum(valor_item) AS valor_total FROM ensaio_chave.fct_id;

\echo == 3. TRUNCATE padrão (CONTINUE IDENTITY) e recarga com as versões do dia 22, desfeito no fim.
BEGIN;
TRUNCATE ensaio_chave.dim_id;
INSERT INTO ensaio_chave.dim_id (produto_id, nome, preco_tabela, valido_de, valido_ate)
SELECT produto_id, nome, preco, valido_de, valido_ate FROM ensaio_chave.versoes_ate(DATE '2026-10-22')
ORDER BY produto_id, valido_de;
SELECT min(produto_sk) AS menor_chave, max(produto_sk) AS maior_chave, count(*) AS versoes FROM ensaio_chave.dim_id;
SELECT count(*) AS orfas_relationships FROM ensaio_chave.fct_id f
LEFT JOIN ensaio_chave.dim_id d USING (produto_sk) WHERE d.produto_sk IS NULL;
ROLLBACK;

\echo == 4. Com chave estrangeira declarada, o banco recusa o TRUNCATE da dimensão.
BEGIN;
ALTER TABLE ensaio_chave.fct_id ADD CONSTRAINT fct_id_produto_fk FOREIGN KEY (produto_sk) REFERENCES ensaio_chave.dim_id (produto_sk);
TRUNCATE ensaio_chave.dim_id RESTART IDENTITY;
ROLLBACK;

\echo == 5. TRUNCATE com RESTART IDENTITY e recarga com as versões do dia 22: a numeração recomeça do 1.
TRUNCATE ensaio_chave.dim_id RESTART IDENTITY;
INSERT INTO ensaio_chave.dim_id (produto_id, nome, preco_tabela, valido_de, valido_ate)
SELECT produto_id, nome, preco, valido_de, valido_ate FROM ensaio_chave.versoes_ate(DATE '2026-10-22')
ORDER BY produto_id, valido_de;
SELECT produto_sk, produto_id, nome, preco_tabela, valido_de, valido_ate FROM ensaio_chave.dim_id ORDER BY produto_sk;

\echo == 6. A mesma chave guardada na fato, antes e depois da reconstrução.
SELECT a.produto_sk, a.nome || ', ' || a.preco_tabela AS antes, d.nome || ', ' || d.preco_tabela AS depois,
       a.nome <> d.nome OR a.preco_tabela <> d.preco_tabela AS mudou
FROM ensaio_chave.leitura_antes a JOIN ensaio_chave.dim_id d USING (produto_sk) ORDER BY 1;

\echo == 7. Itens lidos errado, relatório por produto, total, órfãs e nulos.
SELECT count(*) AS itens, count(*) FILTER (WHERE i.produto_id <> d.produto_id) AS lidos_errado
FROM ensaio_chave.fct_id f JOIN silver.itens i USING (pedido_id, item_seq) JOIN ensaio_chave.dim_id d USING (produto_sk);
SELECT d.nome, count(*) AS itens, sum(f.valor_item) AS valor
FROM ensaio_chave.fct_id f JOIN ensaio_chave.dim_id d USING (produto_sk) GROUP BY 1 ORDER BY 1;
SELECT count(*) AS itens_guardados, sum(valor_item) AS valor_total FROM ensaio_chave.fct_id;
-- Same queries the dbt relationships and not_null tests compile to.
SELECT (SELECT count(*) FROM ensaio_chave.fct_id f LEFT JOIN ensaio_chave.dim_id d USING (produto_sk)
        WHERE f.produto_sk IS NOT NULL AND d.produto_sk IS NULL) AS orfas_relationships,
       (SELECT count(*) FROM ensaio_chave.fct_id WHERE produto_sk IS NULL) AS nulos_not_null;

\echo == 8. Os mesmos dados em ordem inversa de carga, desfeito no fim.
BEGIN;
TRUNCATE ensaio_chave.dim_id RESTART IDENTITY;
INSERT INTO ensaio_chave.dim_id (produto_id, nome, preco_tabela, valido_de, valido_ate)
SELECT produto_id, nome, preco, valido_de, valido_ate FROM ensaio_chave.versoes_ate(DATE '2026-10-22')
ORDER BY produto_id DESC, valido_de DESC;
SELECT count(*) AS itens, count(*) FILTER (WHERE i.produto_id <> d.produto_id) AS lidos_errado
FROM ensaio_chave.fct_id f JOIN silver.itens i USING (pedido_id, item_seq) JOIN ensaio_chave.dim_id d USING (produto_sk);
ROLLBACK;
